@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldCalculateTotalForValidOrder() {
        var order = new Order(1L, "Laptop", 1200.00);
        when(orderRepository.findById(1L)).thenReturn(Optional.of(order));

        var total = orderService.calculateTotal(1L);

        assertEquals(1200.00, total);
        verify(orderRepository).findById(1L);
    }

    @Test
    void shouldThrowExceptionWhenOrderNotFound() {
        when(orderRepository.findById(999L)).thenReturn(Optional.empty());

        assertThrows(OrderNotFoundException.class, 
            () -> orderService.calculateTotal(999L));
    }
}

@WebMvcTest(OrderController.class)
class OrderControllerTest {
    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private OrderService orderService;

    @Test
    void shouldReturnOrderWhenFound() throws Exception {
        var order = new Order(1L, "Laptop", 1200.00);
        when(orderService.findById(1L)).thenReturn(order);

        mockMvc.perform(get("/api/orders/1"))
            .andExpect(status().isOk())
            .andExpect(content().contentType(MediaType.APPLICATION_JSON))
            .andExpect(jsonPath("$.id").value(1))
            .andExpect(jsonPath("$.item").value("Laptop"))
            .andExpect(jsonPath("$.price").value(1200.00));
    }

    @Test
    void shouldReturn404WhenOrderNotFound() throws Exception {
        when(orderService.findById(999L)).thenThrow(new OrderNotFoundException());

        mockMvc.perform(get("/api/orders/999"))
            .andExpect(status().isNotFound());
    }
}

@DataJpaTest
class OrderRepositoryTest {
    @Autowired
    private OrderRepository orderRepository;

    @Autowired
    private TestEntityManager entityManager;

    @Test
    void shouldFindOrdersByStatus() {
        var order1 = new Order(null, "Laptop", 1200.00, OrderStatus.PENDING);
        var order2 = new Order(null, "Mouse", 25.00, OrderStatus.SHIPPED);
        entityManager.persist(order1);
        entityManager.persist(order2);
        entityManager.flush();

        var pending = orderRepository.findByStatus(OrderStatus.PENDING);

        assertEquals(1, pending.size());
        assertEquals("Laptop", pending.get(0).getItem());
    }

    @Test
    void shouldEnforceUniqueConstraintOnOrderNumber() {
        var order1 = new Order(null, "ORD-001", "Keyboard", 75.00);
        entityManager.persistAndFlush(order1);

        var order2 = new Order(null, "ORD-001", "Monitor", 300.00);
        assertThrows(DataIntegrityViolationException.class, 
            () -> entityManager.persistAndFlush(order2));
    }
}

// Unit test: mocked repository, no Spring context
@ExtendWith(MockitoExtension.class)
class OrderServiceUnitTest {
    @Mock
    private OrderRepository orderRepository;
    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldThrowExceptionWhenOrderInvalid() {
        var invalidOrder = new Order(null, "", -100.00);
        assertThrows(InvalidOrderException.class, 
            () -> orderService.createOrder(invalidOrder));
        verify(orderRepository, never()).save(any());
    }
}

// Integration test: real repository, Spring context loaded
@DataJpaTest
class OrderServiceIntegrationTest {
    @Autowired
    private OrderRepository orderRepository;
    private OrderService orderService;

    @BeforeEach
    void setUp() {
        orderService = new OrderService(orderRepository);
    }

    @Test
    void shouldRollbackTransactionOnException() {
        var order = new Order(null, "Laptop", 1200.00);
        assertThrows(RuntimeException.class, 
            () -> orderService.createAndNotify(order));
        assertEquals(0, orderRepository.count()); // rolled back
    }
}

@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {
    @Mock
    private RestTemplate restTemplate;
    @InjectMocks
    private PaymentService paymentService;

    @Test
    void shouldProcessPaymentWhenGatewayApproves() {
        var request = new PaymentRequest("card-123", 100.00);
        var gatewayResponse = new GatewayResponse("approved", "txn-789");

        when(restTemplate.postForObject(
            eq("https://gateway.example.com/charge"),
            eq(request),
            eq(GatewayResponse.class)
        )).thenReturn(gatewayResponse);

        var result = paymentService.processPayment(request);

        assertTrue(result.isSuccess());
        assertEquals("txn-789", result.getTransactionId());
    }

    @Test
    void shouldThrowExceptionWhenGatewayReturnsNull() {
        when(restTemplate.postForObject(anyString(), any(), eq(GatewayResponse.class)))
            .thenReturn(null);

        assertThrows(PaymentGatewayException.class,
            () -> paymentService.processPayment(new PaymentRequest("card-456", 50.00)));
    }
}

@ExtendWith(MockitoExtension.class)
class OrderServiceExceptionTest {
    @Mock
    private OrderRepository orderRepository;
    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldPropagateDataAccessExceptionWhenRepositoryFails() {
        when(orderRepository.findById(1L))
            .thenThrow(new DataAccessException("DB connection timeout") {});

        assertThrows(DataAccessException.class, 
            () -> orderService.findOrder(1L));
    }

    @Test
    void shouldTranslateExceptionIntoOrderNotFoundException() {
        when(orderRepository.findById(999L))
            .thenReturn(Optional.empty());

        var exception = assertThrows(OrderNotFoundException.class, 
            () -> orderService.getOrderOrThrow(999L));

        assertEquals("Order not found: 999", exception.getMessage());
        assertTrue(exception.getMessage().contains("999")); // context preserved
    }

    @Test
    void shouldRollbackTransactionOnBusinessRuleViolation() {
        var order = new Order(1L, "Laptop", -100.00); // invalid price

        assertThrows(InvalidOrderException.class, 
            () -> orderService.createOrder(order));
        verify(orderRepository, never()).save(any()); // never saved
    }
}
